return {["fb306_01"]={["down"]=[[fb306_02]],["dsc"]=[[屋子右侧挂着几把重型兵器，赫赫声威。而屋子左侧却与之不同，摆放了几盆吐露芳蕊的兰花芍药，芳香四溢。这令人诧异的摆设，叫人捉摸不透这屋主的心中所想。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb306_01]],["name"]=[[内屋]],["permission"]=1,["role1"]=[[fb306_17c]],["spaceTime"]=[[内屋]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb306_02"]={["dsc"]=[[院落里，几根长长的竹竿架上爬满了花藤，稠密的绿叶映衬着紫红花朵，娇嫩鲜艳，远远望去，好像一匹美丽的绸缎。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb306_02]],["name"]=[[松竹院]],["permission"]=1,["right"]=[[fb306_03]],["role1"]=[[fb306_16a]],["spaceTime"]=[[松竹院]],["stepMusic"]=[[mudiban]],["up"]=[[fb306_01]],["visible"]=1},["fb306_03"]={["dsc"]=[[冰雪融化形成一条清澈的小溪，从桥下缓缓流过。不时有顽皮的小鱼跃出水面，在阳光下划出一条银白色的弧线。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb306_03]],["left"]=[[fb306_02]],["name"]=[[溪涧]],["permission"]=1,["right"]=[[fb306_04]],["spaceTime"]=[[溪涧]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb306_04"]={["dsc"]=[[院落与阁楼之间的小路上，生长着生机勃勃的翠竹。翠竹和怪石堆叠在一起，突兀嶙峋，气势非凡。]],["enterable"]=1,["fightBackground"]=[[森林外]],["id"]=[[fb306_04]],["left"]=[[fb306_03]],["name"]=[[竹林小路]],["permission"]=1,["rightDown"]=[[fb306_05]],["spaceTime"]=[[竹林小路]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb306_05"]={["dsc"]=[[院落与阁楼之间的小路上，生长着生机勃勃的翠竹。翠竹和怪石堆叠在一起，突兀嶙峋，气势非凡。]],["enterable"]=1,["fightBackground"]=[[森林外]],["id"]=[[fb306_05]],["leftUp"]=[[fb306_04]],["name"]=[[竹林小路]],["permission"]=1,["rightDown"]=[[fb306_06]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb306_06"]={["down"]=[[fb306_09]],["dsc"]=[[后山上到处是一株株巨大无比的松树。遥遥看去, 好似一座座松树之墙耸立其中,将后山道道围起，让人只觉高处不胜寒。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb306_06]],["left"]=[[fb306_32]],["leftUp"]=[[fb306_05]],["name"]=[[后山]],["permission"]=1,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb306_07"]={["down"]=[[fb306_10]],["dsc"]=[[一座密室，出口被一幅画作遮掩，但即便如此，也拦不住你的脚步。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb306_07]],["name"]=[[密室]],["permission"]=1,["role1"]=[[fb306_18a]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb306_08"]={["dsc"]=[[一座安静的红墙小院。小桥流水，小溪从院后绕过，响起潺潺之声。院内设施简朴雅致，让参观者流连忘返。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb306_08]],["name"]=[[松乔院]],["permission"]=1,["right"]=[[fb306_09]],["role1"]=[[zhounianqingsc]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb306_09"]={["dsc"]=[[走廊两边种着许多花草，当然最多的还是梅花。可以想象，寒冬时节，这里一定是梅香四溢，令人陶醉。能住在这种世外梅园也是一种难得的福气了。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb306_09]],["item1"]=[[22znrwcf02]],["left"]=[[fb306_08]],["name"]=[[梅园]],["permission"]=1,["right"]=[[fb306_10]],["role1"]=[[fb306_31a]],["role2"]=[[fb306_30]],["stepMusic"]=[[mudiban]],["up"]=[[fb306_06]],["visible"]=1},["fb306_10"]={["down"]=[[fb306_14]],["dsc"]=[[暖阁春初入，温炉兴稍阑。晚风犹冷在，夜火且留看。暖阁中添一火炉，炉中薪火旺盛，为四周几座院落送上暖意。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb306_10]],["item1"]=[[wp05]],["left"]=[[fb306_09]],["name"]=[[暖阁]],["permission"]=1,["right"]=[[fb306_31]],["role1"]=[[fb306_12]],["stepMusic"]=[[mudiban]],["up"]=[[fb306_07]],["visible"]=1},["fb306_11"]={["down"]=[[fb306_15]],["dsc"]=[[院落里，参天古柏立于中央，郁郁青松生于四角。踏足此地，松脂墨香扑鼻而来，让人提神醒脑。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb306_11]],["item1"]=[[wp04]],["name"]=[[松柏院]],["permission"]=1,["role1"]=[[fb306_28]],["role2"]=[[fb306_19]],["stepMusic"]=[[mudiban]],["up"]=[[fb306_33]],["visible"]=1},["fb306_12"]={["dsc"]=[[已是悬崖百丈冰,犹有花枝俏。山崖上，周围都是云海翻滚,似乎进入了仙境,远处的山峰若隐若现。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb306_12]],["item1"]=[[wp02]],["name"]=[[雪松崖]],["permission"]=1,["right"]=[[fb306_13]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb306_13"]={["down"]=[[fb306_16]],["dsc"]=[[林子里蒙着一种红雾，往上看，树皮都被染成了褐红。地上有绿的草，黄的叶，也有枯干的树枝，倒是那些褐红的松皮落的四处都是，几乎将绿草覆盖了。]],["enterable"]=1,["fightBackground"]=[[森林外]],["id"]=[[fb306_13]],["left"]=[[fb306_12]],["name"]=[[雪山树林]],["permission"]=1,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb306_14"]={["down"]=[[fb306_18]],["dsc"]=[[这是红松阁的大厅，内部摆设极尽豪华，当中一张黑色檀木条案，上面陈放着精美的花瓶和一些珍贵的瓷器，四壁挂满名家的字画。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb306_14]],["item1"]=[[22znwp12]],["name"]=[[山庄大厅]],["permission"]=1,["right"]=[[fb306_15]],["role1"]=[[fb306_07c]],["role2"]=[[fb306_34a]],["stepMusic"]=[[mudiban]],["up"]=[[fb306_10]],["visible"]=1},["fb306_15"]={["dsc"]=[[这里是红松阁后院，各种古玩琳琅满目，商周青铜、汉瓦当、唐三彩，应有尽有，只要拥有一件，就够吃一辈子了。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb306_15]],["left"]=[[fb306_14]],["name"]=[[后院]],["permission"]=1,["right"]=[[fb306_30]],["role1"]=[[fb306_01b]],["stepMusic"]=[[jiaobu]],["up"]=[[fb306_11]],["visible"]=1},["fb306_16"]={["dsc"]=[[林子里蒙着一种红雾，往上看，树皮都被染成了褐红。地上有绿的草，黄的叶，也有枯干的树枝，倒是那些褐红的松皮落的四处都是，几乎将绿草覆盖了。]],["enterable"]=1,["fightBackground"]=[[森林外]],["id"]=[[fb306_16]],["name"]=[[雪山树林]],["permission"]=1,["right"]=[[fb306_17]],["stepMusic"]=[[jiaobu]],["up"]=[[fb306_13]],["visible"]=1},["fb306_17"]={["dsc"]=[[路边是一条溪水，听不见水流，却见满溪的石头，大大小小流成一道河样，真是静水流深。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb306_17]],["left"]=[[fb306_16]],["name"]=[[山溪边]],["permission"]=1,["right"]=[[fb306_18]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb306_18"]={["dsc"]=[[大门梁上雕龙刻凤，美奂美仑，不知凝聚着多少能工巧匠的心血。更显出庄主的富有与显贵。门前左右各蹲着一只威武庄严的石狮子，煞是威风。]],["enterable"]=1,["fightBackground"]=[[城镇室外]],["id"]=[[fb306_18]],["left"]=[[fb306_17]],["name"]=[[红松庄门]],["permission"]=1,["right"]=[[fb306_19]],["role1"]=[[fb306_05a]],["stepMusic"]=[[jiaobu]],["up"]=[[fb306_14]],["visible"]=1},["fb306_19"]={["down"]=[[fb306_21]],["dsc"]=[[这是一条通往山上的泥路，你脚下滑滑的，很不好走，不知道这条路是通向哪里的，也没有人修一修。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb306_19]],["item1"]=[[22znrwcf01]],["item2"]=[[22znrwcf02]],["left"]=[[fb306_18]],["name"]=[[山路]],["permission"]=1,["stepMusic"]=[[jiaobu]],["visible"]=1},["fb306_20"]={["dsc"]=[[路边是一条溪水，听不见水流，却见满溪的石头，大大小小流成一道河样，真是静水流深。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb306_20]],["name"]=[[小溪]],["permission"]=1,["right"]=[[fb306_21]],["role1"]=[[fb306_01]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb306_21"]={["down"]=[[fb306_24]],["dsc"]=[[忽而，一声鸟唳划破了夜色中寂寥的山谷，凭空多了一点生气。这时候，天边的尽头飞来无数鸟群，寒鸦万点，络绎不绝。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb306_21]],["left"]=[[fb306_20]],["name"]=[[翠谷]],["permission"]=1,["right"]=[[fb306_22]],["stepMusic"]=[[jiaobu]],["up"]=[[fb306_19]],["visible"]=1},["fb306_22"]={["dsc"]=[[这是一条通往山上的泥路，你脚下滑滑的，很不好走，不知道这条路是通向哪里的，也没有人修一修。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb306_22]],["left"]=[[fb306_21]],["name"]=[[山路]],["permission"]=1,["right"]=[[fb306_23]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb306_23"]={["dsc"]=[[于山间东侧的山崖，一棵苍松挂于悬崖之上，犹如宝剑冲天，让人顿生感叹。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb306_23]],["left"]=[[fb306_22]],["name"]=[[苍松崖]],["permission"]=1,["role1"]=[[fb306_02a]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb306_24"]={["down"]=[[fb306_26]],["dsc"]=[[林子里蒙着一种红雾，往上看，树皮都被染成了褐红。地上有绿的草，黄的叶，也有枯干的树枝，倒是那些褐红的松皮落的四处都是，几乎将绿草覆盖了。]],["enterable"]=1,["fightBackground"]=[[森林外]],["id"]=[[fb306_24]],["name"]=[[雪松林]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb306_21]],["visible"]=1},["fb306_25"]={["down"]=[[fb306_27]],["dsc"]=[[大片大片的雪花在空中飞舞，像天女撒下的玉叶银花，晶莹美丽。望着蜿蜒起伏的山脉，白雪皑皑，在柔和的月光下映衬皎洁明亮。]],["enterable"]=1,["fightBackground"]=[[森林外]],["id"]=[[fb306_25]],["name"]=[[雪松斜坡]],["permission"]=1,["right"]=[[fb306_26]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb306_26"]={["dsc"]=[[在半山坡上，一个平缓宽阔的空间。平台上鸟语花香，并无高寒之感，似是到了这里，所有风雪都会止步。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb306_26]],["left"]=[[fb306_25]],["name"]=[[大平台]],["permission"]=1,["role1"]=[[fb306_03a]],["role2"]=[[fb306_04a]],["stepMusic"]=[[mudiban]],["up"]=[[fb306_24]],["visible"]=1},["fb306_27"]={["down"]=[[fb306_28]],["dsc"]=[[雪让人的感觉只有一个字——冷。雪地一片银白，一片洁净，而雪花仍如柳絮，如棉花，如鹅毛从天空飘飘洒洒。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb306_27]],["name"]=[[雪地]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb306_25]],["visible"]=1},["fb306_28"]={["dsc"]=[[这是一间破破烂烂的将军庙，庙里破败不堪，将军像推在一旁，梁上地下也布满了灰尘。一看就知道已经很久没有人来清理过了。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb306_28]],["item1"]=[[wp01]],["name"]=[[将军庙]],["permission"]=1,["stepMusic"]=[[mudiban]],["up"]=[[fb306_27]],["visible"]=1},["fb306_29"]={["dsc"]=[[仰望高崖，白雾封谷。谷底，约有三里之宽阔，东南西北尽是悬崖峭壁，绝无出路。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb306_29]],["item1"]=[[wp03]],["name"]=[[谷底]],["permission"]=1,["role1"]=[[fb306_06a]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb306_30"]={["dsc"]=[[只有一扇门的房间，屋内有些昏暗，点燃的烛光映照在冰冷的铁笼之上显得格外瘆人。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb306_30]],["item1"]=[[22znrwcf03]],["item2"]=[[22znrwcf04]],["left"]=[[fb306_15]],["name"]=[[小黑屋]],["permission"]=1,["role1"]=[[fb306_20a]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb306_31"]={["dsc"]=[[仓库中已经堆满了乱七八糟的东西，看样子都是被这个叫南瓜的家伙弄来的。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb306_31]],["item1"]=[[22znwp04]],["left"]=[[fb306_10]],["name"]=[[仓库]],["permission"]=1,["role1"]=[[fb306_27a]],["stepMusic"]=[[mudiban]],["visible"]=1},["fb306_32"]={["dsc"]=[[此处是红松阁后山最高处，站在此处能俯瞰整个红松阁全貌，美不胜收。]],["enterable"]=1,["fightBackground"]=[[山内]],["id"]=[[fb306_32]],["item1"]=[[22znwp05]],["item2"]=[[22znwp06]],["name"]=[[后山山顶]],["permission"]=1,["right"]=[[fb306_06]],["role1"]=[[fb306_29a]],["stepMusic"]=[[jiaobu]],["visible"]=1},["fb306_33"]={["down"]=[[fb306_11]],["dsc"]=[[松柏堂是松柏院附属专门用于存放书籍作品的地方，里面堆积的书本字画不计其数。]],["enterable"]=1,["fightBackground"]=[[城镇室内]],["id"]=[[fb306_33]],["item1"]=[[22znwp07]],["name"]=[[松柏堂]],["permission"]=1,["role1"]=[[fb306_32a]],["stepMusic"]=[[mudiban]],["visible"]=1}}0000000000000